let db,activePlan=null,activeWorkout=null,currentCalendar=new Date(),deferredPrompt=null,timerInterval=null,timerRemaining=0;
const $=id=>document.getElementById(id),qsa=s=>[...document.querySelectorAll(s)],pad=n=>String(n).padStart(2,"0");
const dateKey=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`,brDate=s=>s?s.split("-").reverse().join("/"):"";
const fmt=n=>Number.isFinite(Number(n))?Number(n).toLocaleString("pt-BR",{maximumFractionDigits:1}):"—",clone=o=>JSON.parse(JSON.stringify(o));
function toast(msg){const e=$("toast");e.textContent=msg;e.classList.add("show");clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove("show"),1600)}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE_WORKOUTS)){const s=d.createObjectStore(STORE_WORKOUTS,{keyPath:"id"});s.createIndex("date","date");s.createIndex("plan","plan")}if(!d.objectStoreNames.contains(STORE_SETTINGS))d.createObjectStore(STORE_SETTINGS,{keyPath:"key"});if(!d.objectStoreNames.contains(STORE_RECORDS))d.createObjectStore(STORE_RECORDS,{keyPath:"exercise"});if(!d.objectStoreNames.contains(STORE_NUTRITION))d.createObjectStore(STORE_NUTRITION,{keyPath:"id"});if(!d.objectStoreNames.contains(STORE_MEASURES))d.createObjectStore(STORE_MEASURES,{keyPath:"id"});if(!d.objectStoreNames.contains(STORE_MEDS))d.createObjectStore(STORE_MEDS,{keyPath:"id"});if(!d.objectStoreNames.contains(STORE_PHOTOS))d.createObjectStore(STORE_PHOTOS,{keyPath:"id"})};r.onsuccess=()=>{db=r.result;res(db)};r.onerror=()=>rej(r.error)})}
function st(n,m="readonly"){return db.transaction(n,m).objectStore(n)}
function getAll(n){return new Promise((res,rej)=>{const r=st(n).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function getOne(n,k){return new Promise((res,rej)=>{const r=st(n).get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(n,v){return new Promise((res,rej)=>{const r=st(n,"readwrite").put(v);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function clearStore(n){return new Promise((res,rej)=>{const r=st(n,"readwrite").clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function scheduledPlanForDate(d=new Date()){return ROUTINE.week.find(x=>x.day===d.getDay())?.plan||null}
function newWorkout(plan,date=dateKey(new Date())){const p=ROUTINE.plans[plan];return{id:`${date}_${plan}_${Date.now()}`,date,plan,planName:p.name,templateVersion:ROUTINE.version,routineSnapshot:clone(p),startedAt:new Date().toISOString(),finishedAt:null,notes:"",cardio:null,exercises:p.exercises.map(ex=>({name:ex.name,prescription:clone(ex),notes:"",sets:Array.from({length:ex.sets},(_,i)=>({set:i+1,kg:null,reps:null,rir:null,savedAt:null}))}))}}
function workoutVolume(w){return w.exercises.reduce((a,e)=>a+e.sets.reduce((s,x)=>s+(+x.kg||0)*(+x.reps||0),0),0)}
function completedSets(w){return w.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.savedAt).length,0)} function totalSets(w){return w.exercises.reduce((n,e)=>n+e.sets.length,0)}
async function findDraft(date,plan){return (await getAll(STORE_WORKOUTS)).find(w=>w.date===date&&w.plan===plan&&!w.finishedAt)||null}
async function previousCompletedWorkout(plan,date){return (await getAll(STORE_WORKOUTS)).filter(w=>w.plan===plan&&w.finishedAt&&w.date<date).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
async function saveWorkout(){if(activeWorkout)await put(STORE_WORKOUTS,activeWorkout)}
function rirText(ex){if(ex.rirMin==null)return"RIR livre";return ex.rirMin===ex.rirMax?`RIR ${ex.rirMin}`:`RIR ${ex.rirMin}–${ex.rirMax}`}
function restText(s){if(s>=120&&s%60===0)return`${s/60} min`;if(s>90)return`${Math.floor(s/60)}:${pad(s%60)} min`;return`${s} s`}
function progressionQualified(e){const p=e.prescription;if(p.rirMin==null)return false;const ss=e.sets;if(ss.some(s=>!s.savedAt))return false;return ss.every(s=>+s.reps>=p.repMax&&+s.rir>=p.rirMin)}
async function updateRecordsForWorkout(w){for(const e of w.exercises){const ss=e.sets.filter(s=>s.savedAt);if(!ss.length)continue;const maxLoad=Math.max(...ss.map(s=>+s.kg||0)),maxReps=Math.max(...ss.map(s=>+s.reps||0)),volume=ss.reduce((a,s)=>a+(+s.kg||0)*(+s.reps||0),0);const r=await getOne(STORE_RECORDS,e.name)||{exercise:e.name,maxLoad:0,maxReps:0,maxVolume:0,events:[]};let ch=false;if(maxLoad>r.maxLoad){r.maxLoad=maxLoad;r.events.push({type:"Carga",value:maxLoad,date:w.date});ch=true}if(maxReps>r.maxReps){r.maxReps=maxReps;r.events.push({type:"Repetições",value:maxReps,date:w.date});ch=true}if(volume>r.maxVolume){r.maxVolume=volume;r.events.push({type:"Volume",value:volume,date:w.date});ch=true}if(ch)await put(STORE_RECORDS,r)}}
function switchView(n){qsa(".view").forEach(v=>v.classList.toggle("active",v.id===`view-${n}`));qsa(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===n));if(n==="hoje")renderToday();if(n==="treino")renderWorkoutScreen();if(n==="diario")renderDiary();if(n==="historico")renderHistory();if(n==="calendario")renderCalendar();if(n==="evolucao")renderEvolution()}
qsa(".nav-item").forEach(b=>b.onclick=()=>switchView(b.dataset.view));
async function weightGoalCardHTML(){const goal=await getWeightGoal(),all=(await getAll(STORE_MEASURES)).filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date)),last=all.at(-1);if(!last)return `<div class="card"><h3>🎯 Meta de peso</h3><p class="muted">Meta final: ${fmt(goal.target)} kg. Registre seu peso em Diário → Corpo para acompanhar quanto falta.</p></div>`;const current=+last.weight,start=+goal.start,target=+goal.target,remaining=Math.max(0,current-target),total=start-target,lost=start-current,pct=total>0?Math.max(0,Math.min(100,lost/total*100)):0;return `<div class="card"><h3>🎯 Meta de peso</h3><div class="stats-grid"><div class="stat"><b>${fmt(current)} kg</b><span>peso atual</span></div><div class="stat"><b>${fmt(target)} kg</b><span>meta final</span></div><div class="stat"><b>${fmt(remaining)} kg</b><span>${remaining>0?"faltam":"meta atingida"}</span></div></div><div class="entry-meta" style="margin-top:10px">De ${fmt(start)} kg para ${fmt(target)} kg · ${fmt(pct)}% do caminho</div><div class="progress-mini"><i style="width:${pct}%"></i></div></div>`}
async function renderToday(){const d=new Date(),plan=scheduledPlanForDate(d),hero=$("todayHero"),body=$("todayWorkout"),goalHTML=await weightGoalCardHTML();if(!plan){hero.innerHTML=`<div class="card hero"><div class="hero-kicker">Hoje</div><div class="hero-title">Recuperação</div><div class="hero-sub">Hoje é dia de preservar recuperação. Caminhada ou bike leve são opcionais; não compense o déficit com excesso de cardio.</div></div>`;body.innerHTML=goalHTML;return}const draft=await findDraft(dateKey(d),plan),p=ROUTINE.plans[plan],cardioTxt=p.cardio?` · Bike ${p.cardio.minutesMin}–${p.cardio.minutesMax} min${p.cardio.optional?" opcional":""}`:"";hero.innerHTML=`<div class="card hero"><div class="hero-kicker">Hoje · Treino ${plan}</div><div class="hero-title">${p.name}</div><div class="hero-sub">${p.exercises.length} exercícios${cardioTxt}</div>${p.focus?`<div class="hero-sub">${p.focus}</div>`:""}<button id="startToday" class="btn primary" style="margin-top:14px">${draft?"Continuar treino":"Iniciar treino"}</button></div>`;body.innerHTML=(draft?`<div class="card"><h3>Em andamento</h3><p class="muted">${completedSets(draft)}/${totalSets(draft)} séries registradas.</p></div>`:"")+goalHTML;$("startToday").onclick=async()=>{activePlan=plan;activeWorkout=draft||newWorkout(plan);await saveWorkout();switchView("treino")}}
function renderPlanTabs(){$("planTabs").innerHTML=Object.entries(ROUTINE.plans).map(([k])=>`<button class="${activePlan===k?"active":""}" data-plan="${k}">Treino ${k}</button>`).join("");qsa("[data-plan]").forEach(b=>b.onclick=async()=>{activePlan=b.dataset.plan;activeWorkout=await findDraft(dateKey(new Date()),activePlan)||newWorkout(activePlan);await saveWorkout();renderWorkoutScreen()})}
async function renderWorkoutScreen(){if(!activePlan)activePlan=scheduledPlanForDate(new Date())||"A";if(!activeWorkout||activeWorkout.plan!==activePlan){activeWorkout=await findDraft(dateKey(new Date()),activePlan)||newWorkout(activePlan);await saveWorkout()}renderPlanTabs();const prev=await previousCompletedWorkout(activePlan,activeWorkout.date),plan=activeWorkout.routineSnapshot;let html=`<div class="card"><div class="hero-kicker">Treino ${activePlan}</div><div class="hero-title">${plan.name}</div><div class="hero-sub">${completedSets(activeWorkout)}/${totalSets(activeWorkout)} séries salvas</div></div>`;
for(let i=0;i<activeWorkout.exercises.length;i++){const e=activeWorkout.exercises[i],p=e.prescription,prevE=prev?.exercises?.find(x=>x.name===e.name),last=prevE?prevE.sets.filter(s=>s.savedAt).map(s=>`${fmt(s.kg)}kg×${fmt(s.reps)} @${fmt(s.rir)}`).join(" · "):"Sem treino anterior";html+=`<div class="exercise-card ${e.sets.every(s=>s.savedAt)?"completed":""}"><div class="exercise-header"><div><div class="exercise-name">${i+1}. ${e.name}</div><div class="prescription">${p.sets}×${p.repMin}–${p.repMax} · ${rirText(p)} · descanso ${restText(p.rest)}</div></div><button class="icon-btn" onclick="startTimer(${p.rest})">⏱</button></div><div class="last-session"><b>Último:</b> ${last}</div>${e.sets.map((s,si)=>`<div class="set-row"><div class="set-number">${si+1}</div><label>kg<input inputmode="decimal" type="number" step=".5" id="kg_${i}_${si}" value="${s.kg??""}"></label><label>reps<input inputmode="numeric" type="number" step="1" id="reps_${i}_${si}" value="${s.reps??""}"></label><label>RIR<input inputmode="numeric" type="number" step="1" min="0" max="5" id="rir_${i}_${si}" value="${s.rir??""}"></label><button class="save-set ${s.savedAt?"saved":""}" onclick="saveSet(${i},${si})">${s.savedAt?"✓":"+"}</button></div>`).join("")}<div class="exercise-actions"><button class="notes-toggle" onclick="toggleNote(${i})">📝 Nota do exercício</button><span class="muted">${e.sets.filter(s=>s.savedAt).length}/${e.sets.length} séries</span></div><div id="note_${i}" class="note-box ${e.notes?"open":""}"><textarea id="noteText_${i}" placeholder="Ex.: banco na posição 4...">${e.notes||""}</textarea><button class="btn secondary" onclick="saveExerciseNote(${i})">Salvar nota</button></div>${progressionQualified(e)?`<div class="progress-hint">⬆️ Progressão liberada: você atingiu o topo da faixa em todas as séries com o RIR planejado. Se a técnica esteve boa, aumente a carga pelo menor incremento disponível no próximo treino.</div>`:""}</div>`}
const c=plan.cardio;if(c){html+=`<div class="exercise-card cardio-card"><div class="exercise-name">🚲 Bike ${c.optional?"(opcional)":""}</div><div class="prescription">${c.optional?"Sem sacrificar a recuperação · ":""}${c.minutesMin}–${c.minutesMax} min</div><div class="set-row" style="grid-template-columns:1fr 1fr auto"><label>min<input id="cardioMin" type="number" inputmode="numeric" value="${activeWorkout.cardio?.minutes??""}"></label><label>intensidade<select id="cardioIntensity"><option value="">—</option>${["Leve","Moderada","Intensa","Intervalada"].map(x=>`<option ${activeWorkout.cardio?.intensity===x?"selected":""}>${x}</option>`).join("")}</select></label><button class="save-set ${activeWorkout.cardio?"saved":""}" onclick="saveCardio()">${activeWorkout.cardio?"✓":"+"}</button></div></div>`}html+=`<button id="finishWorkoutBtn" class="btn success" style="width:100%;margin-top:4px">Finalizar treino</button>`;$("workoutEditor").innerHTML=html;$("finishWorkoutBtn").onclick=finishWorkout}
window.saveSet=async(i,si)=>{const kg=Number($(`kg_${i}_${si}`).value),reps=Number($(`reps_${i}_${si}`).value),rr=$(`rir_${i}_${si}`).value;if(!Number.isFinite(kg)||kg<0||!Number.isFinite(reps)||reps<=0){toast("Preencha carga e repetições");return}const rir=rr===""?null:Number(rr),s=activeWorkout.exercises[i].sets[si];Object.assign(s,{kg,reps,rir,savedAt:new Date().toISOString()});await saveWorkout();toast("Série salva");startTimer(activeWorkout.exercises[i].prescription.rest);renderWorkoutScreen()}
window.toggleNote=i=>$(`note_${i}`).classList.toggle("open");
