window.saveCardio=async()=>{activeWorkout.cardio={minutes:Number($("cardioMin").value)||0,intensity:$("cardioIntensity").value,notes:""};await saveWorkout();toast("Bike salva");renderWorkoutScreen()}
async function finishWorkout(){if(!activeWorkout)return;activeWorkout.finishedAt=new Date().toISOString();await saveWorkout();await updateRecordsForWorkout(activeWorkout);toast("Treino finalizado");activeWorkout=null;setTimeout(()=>switchView("historico"),450)}
$("finishWorkoutBtnTop").onclick=finishWorkout;
let timerAudioCtx=null;
function primeTimerAudio(){try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;if(!timerAudioCtx)timerAudioCtx=new AudioCtx();if(timerAudioCtx.state==="suspended")timerAudioCtx.resume().catch(()=>{})}catch(e){console.warn("Áudio do timer indisponível",e)}}
function timerTone(freq,delay=.0,duration=.18,volume=.16){try{if(!timerAudioCtx||timerAudioCtx.state!=="running")return;const ctx=timerAudioCtx,osc=ctx.createOscillator(),gain=ctx.createGain(),t=ctx.currentTime+delay;osc.type="sine";osc.frequency.setValueAtTime(freq,t);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(volume,t+.015);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(t);osc.stop(t+duration+.03)}catch(e){console.warn("Falha ao tocar alarme",e)}}
function playRestAlarm(){primeTimerAudio();timerTone(880,0,.2,.18);timerTone(988,.28,.2,.18);timerTone(1175,.56,.28,.2);if(navigator.vibrate)navigator.vibrate([220,100,220,100,350])}
function startTimer(sec){clearInterval(timerInterval);primeTimerAudio();timerRemaining=sec||90;$("timerBar").classList.remove("hidden");updateTimerText();timerInterval=setInterval(()=>{timerRemaining--;updateTimerText();if(timerRemaining<=0){clearInterval(timerInterval);timerRemaining=0;updateTimerText();playRestAlarm();toast("Descanso concluído 🔔")}},1000)}window.startTimer=startTimer;
function updateTimerText(){$("timerText").textContent=`${pad(Math.floor(timerRemaining/60))}:${pad(timerRemaining%60)}`}
$("timerMinus").onclick=()=>{timerRemaining=Math.max(0,timerRemaining-15);updateTimerText()};$("timerPlus").onclick=()=>{timerRemaining+=15;updateTimerText()};$("timerStop").onclick=()=>{clearInterval(timerInterval);$("timerBar").classList.add("hidden")};
async function renderHistory(){const all=(await getAll(STORE_WORKOUTS)).filter(w=>w.finishedAt).sort((a,b)=>b.date.localeCompare(a.date)),now=new Date(),ws=new Date(now);ws.setDate(now.getDate()-((now.getDay()+6)%7));ws.setHours(0,0,0,0);const mp=dateKey(now).slice(0,7),weekly=all.filter(w=>new Date(w.date+"T00:00:00")>=ws).length,monthly=all.filter(w=>w.date.startsWith(mp)).length;$("historyStats").innerHTML=`<div class="stat"><b>${weekly}</b><span>treinos esta semana</span></div><div class="stat"><b>${monthly}</b><span>treinos este mês</span></div>`;$("historyList").innerHTML=all.length?all.map(w=>`<div class="history-item"><div class="history-top"><div class="history-title">${brDate(w.date)} · Treino ${w.plan}</div><div>${fmt(workoutVolume(w))} kg</div></div><div class="history-meta">${w.planName} · ${completedSets(w)} séries · ${w.cardio?.minutes?`Bike ${w.cardio.minutes} min`:"sem bike"}</div><details><summary class="history-expand">Ver detalhes</summary><div class="history-expand">${w.exercises.map(e=>`<div style="margin:8px 0"><b>${e.name}</b><br>${e.sets.filter(s=>s.savedAt).map(s=>`${fmt(s.kg)}kg × ${fmt(s.reps)} · RIR ${fmt(s.rir)}`).join(" | ")||"—"}${e.notes?`<br><span class="muted">${e.notes}</span>`:""}</div>`).join("")}</div></details></div>`).join(""):`<div class="card"><p class="muted">Nenhum treino finalizado ainda.</p></div>`}
async function renderCalendar(){const all=(await getAll(STORE_WORKOUTS)).filter(w=>w.finishedAt),trained=new Set(all.map(w=>w.date)),y=currentCalendar.getFullYear(),m=currentCalendar.getMonth();$("calendarTitle").textContent=new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(currentCalendar);const first=new Date(y,m,1),last=new Date(y,m+1,0),cells=[];for(let i=0;i<first.getDay();i++)cells.push({d:new Date(y,m,1-first.getDay()+i),muted:true});for(let day=1;day<=last.getDate();day++)cells.push({d:new Date(y,m,day),muted:false});while(cells.length%7)cells.push({d:new Date(y,m+1,cells.length-(first.getDay()+last.getDate())+1),muted:true});const t=dateKey(new Date());$("calendarGrid").innerHTML=cells.map(c=>{const k=dateKey(c.d);return`<div class="day ${c.muted?"muted":""} ${trained.has(k)?"trained":""} ${k===t?"today":""}">${c.d.getDate()}</div>`}).join("")}
$("prevMonth").onclick=()=>{currentCalendar=new Date(currentCalendar.getFullYear(),currentCalendar.getMonth()-1,1);renderCalendar()};$("nextMonth").onclick=()=>{currentCalendar=new Date(currentCalendar.getFullYear(),currentCalendar.getMonth()+1,1);renderCalendar()};
async function allExerciseNames(){const s=new Set();Object.values(ROUTINE.plans).forEach(p=>p.exercises.forEach(e=>s.add(e.name)));(await getAll(STORE_WORKOUTS)).forEach(w=>w.exercises?.forEach(e=>s.add(e.name)));return[...s].sort((a,b)=>a.localeCompare(b,"pt-BR"))}
async function renderEvolution(){const names=await allExerciseNames(),sel=$("evolutionExercise"),cur=sel.value;sel.innerHTML=names.map(n=>`<option>${n}</option>`).join("");if(cur&&names.includes(cur))sel.value=cur;if(!sel.value)return;const name=sel.value,all=(await getAll(STORE_WORKOUTS)).filter(w=>w.finishedAt).sort((a,b)=>a.date.localeCompare(b.date)),points=[];all.forEach(w=>{const e=w.exercises.find(x=>x.name===name);if(!e)return;const ss=e.sets.filter(s=>s.savedAt);if(!ss.length)return;points.push({date:w.date,maxLoad:Math.max(...ss.map(s=>+s.kg||0)),maxReps:Math.max(...ss.map(s=>+s.reps||0)),volume:ss.reduce((a,s)=>a+(+s.kg||0)*(+s.reps||0),0)})});const rec=await getOne(STORE_RECORDS,name);$("evolutionSummary").innerHTML=`<div class="stat"><b>${fmt(rec?.maxLoad||0)} kg</b><span>recorde de carga</span></div><div class="stat"><b>${fmt(rec?.maxReps||0)}</b><span>recorde de reps</span></div><div class="stat"><b>${fmt(rec?.maxVolume||0)} kg</b><span>maior volume</span></div><div class="stat"><b>${points.length}</b><span>sessões registradas</span></div>`;drawChart($("chartLoad"),points.map(p=>({x:p.date,y:p.maxLoad})));drawChart($("chartVolume"),points.map(p=>({x:p.date,y:p.volume})));$("recordsList").innerHTML=rec?.events?.length?`<div class="card"><h3>Recordes pessoais</h3>${[...rec.events].reverse().slice(0,12).map(e=>`<div class="record"><span>${e.type} · ${brDate(e.date)}</span><b>${fmt(e.value)}${e.type==="Carga"?" kg":e.type==="Volume"?" kg":""}</b></div>`).join("")}</div>`:""}
$("evolutionExercise").onchange=renderEvolution;
function drawChart(c,pts){const x=c.getContext("2d"),W=c.width,H=c.height,p=42;x.clearRect(0,0,W,H);x.fillStyle="#0c1118";x.fillRect(0,0,W,H);if(!pts.length){x.fillStyle="#798596";x.font="26px system-ui";x.textAlign="center";x.fillText("Sem dados ainda",W/2,H/2);return}const ys=pts.map(o=>o.y),mn=Math.min(...ys),mx=Math.max(...ys),r=Math.max(1,mx-mn);x.strokeStyle="#263042";x.lineWidth=2;for(let i=0;i<4;i++){const yy=p+i*(H-2*p)/3;x.beginPath();x.moveTo(p,yy);x.lineTo(W-p,yy);x.stroke()}x.strokeStyle="#e9a6c8";x.lineWidth=5;x.beginPath();pts.forEach((o,i)=>{const xx=p+(pts.length===1?0:i*(W-2*p)/(pts.length-1)),yy=H-p-(o.y-mn)*((H-2*p)/r);i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke();x.fillStyle="#e9a6c8";pts.forEach((o,i)=>{const xx=p+(pts.length===1?0:i*(W-2*p)/(pts.length-1)),yy=H-p-(o.y-mn)*((H-2*p)/r);x.beginPath();x.arc(xx,yy,7,0,Math.PI*2);x.fill()})}
$("exportBtn").onclick=async()=>{const photos=await getAll(STORE_PHOTOS),photosExport=[];for(const p of photos){let dataUrl=null;if(p.blob)dataUrl=await blobToDataURL(p.blob);photosExport.push({...p,blob:undefined,dataUrl})}const data={app:"Penelope VII",exportedAt:new Date().toISOString(),routine:ROUTINE,workouts:await getAll(STORE_WORKOUTS),settings:await getAll(STORE_SETTINGS),records:await getAll(STORE_RECORDS),nutrition:await getAll(STORE_NUTRITION),measures:await getAll(STORE_MEASURES),meds:await getAll(STORE_MEDS),photos:photosExport},blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`penelope_VII_backup_${dateKey(new Date())}.json`;a.click();URL.revokeObjectURL(a.href)};
$("importInput").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d.workouts))throw 0;for(const s of [STORE_WORKOUTS,STORE_SETTINGS,STORE_RECORDS,STORE_NUTRITION,STORE_MEASURES,STORE_MEDS,STORE_PHOTOS])await clearStore(s);for(const x of d.workouts)await put(STORE_WORKOUTS,x);for(const x of(d.settings||[]))await put(STORE_SETTINGS,x);for(const x of(d.records||[]))await put(STORE_RECORDS,x);for(const x of(d.nutrition||[]))await put(STORE_NUTRITION,x);for(const x of(d.measures||[]))await put(STORE_MEASURES,x);for(const x of(d.meds||[]))await put(STORE_MEDS,x);for(const x of(d.photos||[])){let blob=null;if(x.dataUrl)blob=dataURLToBlob(x.dataUrl);await put(STORE_PHOTOS,{...x,dataUrl:undefined,blob})}toast("Backup restaurado");renderHistory()}catch(err){console.error(err);toast("Backup inválido")}};

function todayISO(){return dateKey(new Date())}function uid(prefix){return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`}function num(id){const v=$(id)?.value;return v===""||v==null?null:Number(v)}async function getSetting(key,def=null){const x=await getOne(STORE_SETTINGS,key);return x?.value??def}async function setSetting(key,value){return put(STORE_SETTINGS,{key,value})}
async function getWeightGoal(){const g=await getSetting("weightGoal",DEFAULT_WEIGHT_GOAL);return {...DEFAULT_WEIGHT_GOAL,...(g||{})}}
function initDiaryDates(){for(const id of ["foodDate","measureDate","photoDate","medDate"])if($(id)&&!$(id).value)$(id).value=todayISO()}
function bindDiaryTabs(){qsa("[data-diary-tab]").forEach(b=>b.onclick=()=>{qsa("[data-diary-tab]").forEach(x=>x.classList.toggle("active",x===b));qsa(".diary-panel").forEach(p=>p.classList.toggle("active",p.id===`diary-${b.dataset.diaryTab}`));renderDiaryPanel(b.dataset.diaryTab)})}
async function renderDiary(){initDiaryDates();bindDiaryTabs();await loadNutritionGoals();const active=qsa("[data-diary-tab]").find(b=>b.classList.contains("active"))?.dataset.diaryTab||"alimentacao";await renderDiaryPanel(active)}
async function renderDiaryPanel(tab){if(tab==="alimentacao")await renderNutrition();if(tab==="corpo")await renderMeasures();if(tab==="fotos")await renderPhotos();if(tab==="tirzepatida")await renderMeds()}

const normalizeFoodText=s=>(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
function findFoodReference(text){const q=normalizeFoodText(text);if(!q)return null;return FOOD_DB.find(f=>normalizeFoodText(f.name)===q||(f.aliases||[]).some(a=>normalizeFoodText(a)===q))||null}
function populateFoodDatabase(){const dl=$("foodDatabaseList");if(!dl)return;dl.innerHTML=FOOD_DB.map(f=>`<option value="${f.name}"></option>`).join("")}
function setFoodUnitOptions(food){const sel=$("foodUnit");if(!sel)return;const current=sel.value;let opts=[];if(food){opts.push(food.basis);if(food.unitWeight)opts.push("un")}else opts=["g","ml","un"];opts=[...new Set(opts)];sel.innerHTML=opts.map(u=>`<option value="${u}">${u==="un"?"unidade":u}</option>`).join("");sel.value=opts.includes(current)?current:opts[0]}
function clearFoodMacros(){for(const id of ["foodKcal","foodProtein","foodCarbs","foodFat","foodFiber"])$(id).value=""}
function updateFoodCalculation(){const name=$("foodName")?.value||"",food=findFoodReference(name),qty=Number($("foodQty")?.value),unit=$("foodUnit")?.value,status=$("foodCalcStatus");if(!food){setFoodUnitOptions(null);if(status){status.className="food-calc-status";status.textContent=name.trim()?"Não encontrei esse alimento no banco. Você pode preencher os valores manualmente.":"Escolha um alimento do banco para cálculo automático."}return}setFoodUnitOptions(food);const actualUnit=$("foodUnit").value;if(!Number.isFinite(qty)||qty<=0){if(status){status.className="food-calc-status found";status.textContent=`${food.name}: informe a quantidade para calcular.`}return}let amount100=null,detail="";if(actualUnit===food.basis){amount100=qty/100;detail=`${fmt(qty)} ${actualUnit}`}else if(actualUnit==="un"&&food.unitWeight){amount100=(qty*food.unitWeight)/100;detail=`${fmt(qty)} un ≈ ${fmt(qty*food.unitWeight)} ${food.basis}`}if(amount100==null){if(status){status.className="food-calc-status warnbox";status.textContent="Unidade incompatível com este alimento. Escolha outra unidade."}return}const vals={foodKcal:food.kcal*amount100,foodProtein:food.protein*amount100,foodCarbs:food.carbs*amount100,foodFat:food.fat*amount100,foodFiber:food.fiber*amount100};for(const [id,v] of Object.entries(vals))$(id).value=(Math.round(v*10)/10).toString();if(status){status.className="food-calc-status found";status.textContent=`✓ Estimativa automática para ${detail}. Você pode editar os valores antes de salvar.`}$("foodName").dataset.foodKey=food.key}
function bindFoodCalculator(){populateFoodDatabase();const n=$("foodName"),q=$("foodQty"),u=$("foodUnit");if(!n||n.dataset.calcBound)return;n.dataset.calcBound="1";n.addEventListener("input",()=>{const f=findFoodReference(n.value);if(f)setFoodUnitOptions(f);updateFoodCalculation()});n.addEventListener("change",()=>{const f=findFoodReference(n.value);if(f){n.value=f.name;setFoodUnitOptions(f)}updateFoodCalculation()});q?.addEventListener("input",updateFoodCalculation);u?.addEventListener("change",updateFoodCalculation)}

async function loadNutritionGoals(){let rec=await getOne(STORE_SETTINGS,"nutritionGoals");if(!rec){await setSetting("nutritionGoals",DEFAULT_NUTRITION_GOALS);rec={value:DEFAULT_NUTRITION_GOALS}}const g=rec.value||DEFAULT_NUTRITION_GOALS,map={goalKcal:"kcal",goalProtein:"protein",goalCarbs:"carbs",goalFat:"fat",goalFiber:"fiber",goalWater:"water"};for(const [id,k] of Object.entries(map))if($(id))$(id).value=g[k]??""}
$("saveNutritionGoals").onclick=async()=>{const g={kcal:num("goalKcal"),protein:num("goalProtein"),carbs:num("goalCarbs"),fat:num("goalFat"),fiber:num("goalFiber"),water:num("goalWater")};await setSetting("nutritionGoals",g);toast("Metas salvas");renderNutrition()};
async function renderNutrition(){const d=$("foodDate").value||todayISO(),rows=(await getAll(STORE_NUTRITION)).filter(x=>x.date===d).sort((a,b)=>(a.createdAt||"").localeCompare(b.createdAt||"")),t=rows.reduce((a,x)=>{if(x.type==="water")a.water+=(+x.ml||0);else{a.kcal+=(+x.kcal||0);a.protein+=(+x.protein||0);a.carbs+=(+x.carbs||0);a.fat+=(+x.fat||0);a.fiber+=(+x.fiber||0)}return a},{kcal:0,protein:0,carbs:0,fat:0,fiber:0,water:0}),g=await getSetting("nutritionGoals",DEFAULT_NUTRITION_GOALS),cards=[["Calorias","kcal","kcal"],["Proteína","protein","g"],["Carbo","carbs","g"],["Gorduras","fat","g"],["Fibras","fiber","g"]];$("nutritionSummary").innerHTML=cards.map(([lab,k,u])=>{const goal=+g[k]||0,pct=goal?Math.min(100,t[k]/goal*100):0;return `<div class="nutrition-card"><b>${fmt(t[k])}${u==="g"?" g":""}</b><span>${lab}${goal?` / ${fmt(goal)}${u==="g"?" g":""}`:""}</span><div class="progress-mini"><i style="width:${pct}%"></i></div></div>`}).join("");$("waterTotal").textContent=`${Math.round(t.water)} ml${g.water?` / ${Math.round(g.water)} ml`:""}`;const foods=rows.filter(x=>x.type==="food");$("foodEntries").innerHTML=foods.length?foods.map(x=>`<div class="food-entry"><div class="entry-top"><div><div class="entry-title">${x.name}</div><div class="entry-meta">${x.meal} · ${x.qty??""} ${x.unit??""} · ${fmt(x.kcal)} kcal · P ${fmt(x.protein)}g · C ${fmt(x.carbs)}g · G ${fmt(x.fat)}g · Fibras ${fmt(x.fiber)}g${x.estimated?" · estimado":""}</div>${x.photoDataUrl?`<img class="meal-thumb" src="${x.photoDataUrl}" alt="Foto da refeição">`:""}</div><button class="danger-mini" onclick="deleteDiaryItem('${STORE_NUTRITION}','${x.id}','alimentacao')">Excluir</button></div></div>`).join(""):`<div class="card"><p class="muted">Nenhum alimento registrado neste dia.</p></div>`}
$("foodDate").onchange=renderNutrition;$("saveFoodBtn").onclick=async()=>{const name=$("foodName").value.trim();if(!name){toast("Informe o alimento");return}const ref=findFoodReference(name);let photoDataUrl=null;const photo=$("foodPhoto")?.files?.[0];if(photo){try{const blob=await compressImage(photo,1000,.78);photoDataUrl=await blobToDataURL(blob)}catch(e){console.error(e);toast("A foto não pôde ser processada")}}await put(STORE_NUTRITION,{id:uid("food"),type:"food",date:$("foodDate").value||todayISO(),meal:$("mealType").value,name:ref?.name||name,qty:num("foodQty"),unit:$("foodUnit").value,kcal:num("foodKcal")||0,protein:num("foodProtein")||0,carbs:num("foodCarbs")||0,fat:num("foodFat")||0,fiber:num("foodFiber")||0,foodKey:ref?.key||null,estimated:!!ref,photoDataUrl,createdAt:new Date().toISOString()});for(const id of ["foodName","foodQty","foodKcal","foodProtein","foodCarbs","foodFat","foodFiber"])$(id).value="";setFoodUnitOptions(null);if($("foodPhoto"))$("foodPhoto").value="";if($("foodCalcStatus")){$("foodCalcStatus").className="food-calc-status";$("foodCalcStatus").textContent="Escolha um alimento do banco para cálculo automático."}toast("Alimento salvo");renderNutrition()};qsa("[data-water]").forEach(b=>b.onclick=async()=>{await put(STORE_NUTRITION,{id:uid("water"),type:"water",date:$("foodDate").value||todayISO(),ml:+b.dataset.water,createdAt:new Date().toISOString()});toast("Água registrada");renderNutrition()});
async function renderMeasures(){const all=(await getAll(STORE_MEASURES)).sort((a,b)=>a.date.localeCompare(b.date)),last=all.at(-1),prev=all.at(-2),goal=await getWeightGoal();if($("goalStartWeight"))$("goalStartWeight").value=goal.start;if($("goalTargetWeight"))$("goalTargetWeight").value=goal.target;const current=last?.weight!=null?+last.weight:null,remaining=current!=null?Math.max(0,current-(+goal.target)):null,total=(+goal.start)-(+goal.target),lost=current!=null?(+goal.start)-current:0,pct=current!=null&&total>0?Math.max(0,Math.min(100,lost/total*100)):0;if($("weightGoalProgress"))$("weightGoalProgress").innerHTML=current!=null?`<div class="entry-meta" style="margin-top:12px">Atual ${fmt(current)} kg · Meta ${fmt(goal.target)} kg · ${remaining>0?`Faltam ${fmt(remaining)} kg`:"Meta atingida 🎉"}</div><div class="progress-mini"><i style="width:${pct}%"></i></div><div class="muted" style="margin-top:6px">${fmt(pct)}% do caminho desde ${fmt(goal.start)} kg</div>`:`<p class="muted" style="margin-top:12px">Registre seu peso para ver o progresso até a meta.</p>`;$("measureSummary").innerHTML=last?`<div class="stat"><b>${last.weight!=null?fmt(last.weight)+" kg":"—"}</b><span>peso atual</span></div><div class="stat"><b>${fmt(goal.target)} kg</b><span>meta final</span></div><div class="stat"><b>${remaining!=null?fmt(remaining)+" kg":"—"}</b><span>faltam para a meta</span></div><div class="stat"><b>${last.bodyFat!=null?fmt(last.bodyFat)+"%":"—"}</b><span>gordura corporal</span></div><div class="stat"><b>${last.waist!=null?fmt(last.waist)+" cm":"—"}</b><span>cintura</span></div><div class="stat"><b>${prev&&last.weight!=null&&prev.weight!=null?fmt(last.weight-prev.weight)+" kg":"—"}</b><span>variação anterior</span></div>`:`<div class="stat"><b>${fmt(goal.target)} kg</b><span>meta final</span></div>`;drawChart($("chartWeight"),all.filter(x=>x.weight!=null).map(x=>({x:x.date,y:+x.weight})));drawChart($("chartBodyFat"),all.filter(x=>x.bodyFat!=null).map(x=>({x:x.date,y:+x.bodyFat})));$("measureHistory").innerHTML=[...all].reverse().map(x=>`<div class="measure-entry"><div class="entry-top"><div><div class="entry-title">${brDate(x.date)}</div><div class="entry-meta">${x.weight!=null?`Peso ${fmt(x.weight)} kg · `:""}${x.bodyFat!=null?`Gordura ${fmt(x.bodyFat)}% · `:""}${x.waist!=null?`Cintura ${fmt(x.waist)} cm · `:""}${x.hip!=null?`Quadril ${fmt(x.hip)} cm`:""}</div></div><button class="danger-mini" onclick="deleteDiaryItem('${STORE_MEASURES}','${x.id}','corpo')">Excluir</button></div></div>`).join("")}
$("saveWeightGoalBtn").onclick=async()=>{const start=num("goalStartWeight"),target=num("goalTargetWeight");if(start==null||target==null||start<=target){toast("Confira o peso inicial e a meta");return}await setSetting("weightGoal",{start,target});toast("Meta de peso salva 🎯");await renderMeasures();renderToday()};
$("saveMeasureBtn").onclick=async()=>{await put(STORE_MEASURES,{id:uid("measure"),date:$("measureDate").value||todayISO(),weight:num("mWeight"),bodyFat:num("mBodyFat"),bust:num("mBust"),waist:num("mWaist"),abdomen:num("mAbdomen"),hip:num("mHip"),thigh:num("mThigh"),arm:num("mArm"),createdAt:new Date().toISOString()});toast("Medidas salvas");await renderMeasures();renderToday()};
function compressImage(file,maxSize=1280,quality=.82){return new Promise((res,rej)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let w=img.width,h=img.height;if(Math.max(w,h)>maxSize){const s=maxSize/Math.max(w,h);w=Math.round(w*s);h=Math.round(h*s)}const c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(img,0,0,w,h);c.toBlob(blob=>{URL.revokeObjectURL(url);blob?res(blob):rej(new Error("Falha"))},"image/jpeg",quality)};img.onerror=()=>rej(new Error("Imagem inválida"));img.src=url})}
async function renderPhotos(){const all=(await getAll(STORE_PHOTOS)).sort((a,b)=>b.date.localeCompare(a.date));$("photoGallery").innerHTML="";for(const x of all){const url=x.blob?URL.createObjectURL(x.blob):"",div=document.createElement("div");div.className="photo-card";div.innerHTML=`${url?`<img src="${url}" alt="Foto de evolução ${x.pose}">`:""}<div class="photo-info"><b>${x.pose} · ${brDate(x.date)}</b><span>${x.note||""}</span></div><div class="photo-actions"><button class="danger-mini">Excluir</button></div>`;div.querySelector("button").onclick=()=>deleteDiaryItem(STORE_PHOTOS,x.id,"fotos");$("photoGallery").appendChild(div)}if(!all.length)$("photoGallery").innerHTML=`<div class="card"><p class="muted">Nenhuma foto registrada ainda.</p></div>`}
$("savePhotoBtn").onclick=async()=>{const f=$("photoFile").files[0];if(!f){toast("Escolha uma foto");return}try{const blob=await compressImage(f);await put(STORE_PHOTOS,{id:uid("photo"),date:$("photoDate").value||todayISO(),pose:$("photoPose").value,note:$("photoNote").value.trim(),blob,createdAt:new Date().toISOString()});$("photoFile").value="";$("photoNote").value="";toast("Foto salva");renderPhotos()}catch(e){console.error(e);toast("Não foi possível salvar a foto")}};
async function renderMeds(){const all=(await getAll(STORE_MEDS)).sort((a,b)=>b.date.localeCompare(a.date));$("medHistory").innerHTML=all.length?all.map(x=>`<div class="med-entry"><div class="entry-top"><div><div class="entry-title">${brDate(x.date)} · ${x.dose!=null?fmt(x.dose)+" mg":"dose não informada"}</div><div class="entry-meta">${x.site||""}${x.weight!=null?` · ${fmt(x.weight)} kg`:""}${x.notes?` · ${x.notes}`:""}</div></div><button class="danger-mini" onclick="deleteDiaryItem('${STORE_MEDS}','${x.id}','tirzepatida')">Excluir</button></div></div>`).join(""):`<div class="card"><p class="muted">Nenhuma aplicação registrada.</p></div>`}
$("saveMedBtn").onclick=async()=>{await put(STORE_MEDS,{id:uid("med"),date:$("medDate").value||todayISO(),dose:num("medDose"),site:$("medSite").value,weight:num("medWeight"),notes:$("medNotes").value.trim(),createdAt:new Date().toISOString()});$("medDose").value="";$("medWeight").value="";$("medNotes").value="";toast("Aplicação registrada");renderMeds()};
window.deleteDiaryItem=async(storeName,id,tab)=>{const tx=db.transaction(storeName,"readwrite"),req=tx.objectStore(storeName).delete(id);await new Promise((res,rej)=>{req.onsuccess=()=>res();req.onerror=()=>rej(req.error)});toast("Registro excluído");renderDiaryPanel(tab)};function blobToDataURL(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)})}function dataURLToBlob(dataURL){const [meta,b64]=dataURL.split(","),mime=(meta.match(/data:(.*?);base64/)||[])[1]||"application/octet-stream",bin=atob(b64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}

window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredPrompt=e;$("installBtn").classList.remove("hidden")});$("installBtn").onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$("installBtn").classList.add("hidden")};window.addEventListener("appinstalled",()=>toast("Penelope VII instalada"));
